BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version int PRIMARY KEY);
CREATE TABLE departments(id uuid PRIMARY KEY, name text NOT NULL UNIQUE, daily_target bigint NOT NULL DEFAULT 10000000 CHECK(daily_target>0), max_hops int CHECK(max_hops>0), overdue_minutes int NOT NULL DEFAULT 120 CHECK(overdue_minutes>0), gamification boolean NOT NULL DEFAULT false);
CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, pin_hash text NOT NULL, active boolean NOT NULL DEFAULT true, failures int NOT NULL DEFAULT 0, locked_until timestamptz, session_version int NOT NULL DEFAULT 0);
CREATE TABLE role_assignments(user_id uuid PRIMARY KEY REFERENCES users(id), department_id uuid REFERENCES departments(id), role text NOT NULL CHECK(role IN ('SUPER_ADMIN','HOD','COLLECTOR')), CHECK((role='SUPER_ADMIN')=(department_id IS NULL)));
CREATE UNIQUE INDEX one_hod ON role_assignments(department_id) WHERE role='HOD';
CREATE TABLE devices(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), public_key text NOT NULL, active boolean NOT NULL DEFAULT true, enrolled_at timestamptz NOT NULL DEFAULT now(), attestation_review text NOT NULL);
CREATE TABLE sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),device_id uuid NOT NULL REFERENCES devices(id),refresh_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 0);
CREATE TABLE challenges(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),device_id uuid NOT NULL REFERENCES devices(id),action text NOT NULL,payload_hash text NOT NULL,nonce text NOT NULL,expires_at timestamptz NOT NULL,used boolean NOT NULL DEFAULT false);
CREATE TABLE customers(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),name text NOT NULL,contact_ciphertext bytea);
CREATE TABLE cash_collections(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),customer_id uuid NOT NULL REFERENCES customers(id),created_by uuid NOT NULL REFERENCES users(id),amount bigint NOT NULL CHECK(amount>0 AND amount<=9000000000000000),state text NOT NULL CHECK(state IN ('CREATED','IN_CUSTODY','HANDED_TO_HOD','APPROVED')),receipt_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz);
CREATE TABLE custody_positions(collection_id uuid NOT NULL REFERENCES cash_collections(id),department_id uuid NOT NULL REFERENCES departments(id),holder_id uuid NOT NULL REFERENCES users(id),amount bigint NOT NULL CHECK(amount>=0),reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0),blocked bigint NOT NULL DEFAULT 0 CHECK(blocked>=0),hops int NOT NULL DEFAULT 0,CHECK(reserved+blocked<=amount),PRIMARY KEY(collection_id,holder_id));
CREATE TABLE handovers(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),sender_id uuid NOT NULL REFERENCES users(id),receiver_id uuid NOT NULL REFERENCES users(id),expected bigint NOT NULL CHECK(expected>0),state text NOT NULL CHECK(state IN ('INITIATED','PENDING_RECEIPT','RECEIVED','DISPUTED','REJECTED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(sender_id<>receiver_id));
CREATE TABLE handover_allocations(handover_id uuid NOT NULL REFERENCES handovers(id),collection_id uuid NOT NULL REFERENCES cash_collections(id),department_id uuid NOT NULL REFERENCES departments(id),amount bigint NOT NULL CHECK(amount>0),PRIMARY KEY(handover_id,collection_id));
CREATE TABLE receipt_confirmations(id uuid PRIMARY KEY,handover_id uuid NOT NULL UNIQUE REFERENCES handovers(id),department_id uuid NOT NULL REFERENCES departments(id),receiver_id uuid NOT NULL REFERENCES users(id),actual bigint NOT NULL CHECK(actual>=0),confirmed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE custody_ledger_entries(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),collection_id uuid NOT NULL REFERENCES cash_collections(id),handover_id uuid REFERENCES handovers(id),from_user uuid REFERENCES users(id),to_user uuid NOT NULL REFERENCES users(id),amount bigint NOT NULL CHECK(amount>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hod_approvals(collection_id uuid PRIMARY KEY REFERENCES cash_collections(id),department_id uuid NOT NULL REFERENCES departments(id),hod_id uuid REFERENCES users(id),state text NOT NULL DEFAULT 'PENDING_HOD' CHECK(state IN ('PENDING_HOD','UNDER_REVIEW','APPROVED','DISCREPANCY_OPEN','REJECTED')),reason text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE discrepancies(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),handover_id uuid REFERENCES handovers(id),collection_id uuid REFERENCES cash_collections(id),expected bigint NOT NULL,actual bigint NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','RESOLVED')),resolution text,resolved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_handover_discrepancy ON discrepancies(handover_id) WHERE handover_id IS NOT NULL;
CREATE TABLE adjustments(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),collection_id uuid NOT NULL REFERENCES cash_collections(id),delta bigint NOT NULL CHECK(delta<>0),reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachments(id uuid PRIMARY KEY,department_id uuid NOT NULL REFERENCES departments(id),collection_id uuid NOT NULL REFERENCES cash_collections(id),object_key text NOT NULL UNIQUE,sha256 text NOT NULL,content_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(seq bigserial PRIMARY KEY,id uuid NOT NULL UNIQUE,department_id uuid REFERENCES departments(id),actor_id uuid NOT NULL REFERENCES users(id),role text NOT NULL,action text NOT NULL,reason text,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now(),prev_hash text NOT NULL,event_hash text NOT NULL);
CREATE TABLE idempotency_records(user_id uuid NOT NULL REFERENCES users(id),key uuid NOT NULL,department_id uuid REFERENCES departments(id),request_hash text NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE INDEX collection_dept_date ON cash_collections(department_id,created_at DESC);
CREATE INDEX incoming_tasks ON handovers(receiver_id,state,created_at);
CREATE INDEX outgoing_tasks ON handovers(sender_id,state,created_at);
CREATE INDEX open_discrepancies ON discrepancies(department_id,state);
CREATE INDEX ledger_chain ON custody_ledger_entries(collection_id,created_at);
CREATE INDEX audit_dept_seq ON audit_events(department_id,seq);
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only record'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON custody_ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER adjustments_immutable BEFORE UPDATE OR DELETE ON adjustments FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER confirmations_immutable BEFORE UPDATE OR DELETE ON receipt_confirmations FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE FUNCTION protect_approved() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='APPROVED' THEN RAISE EXCEPTION 'approved record is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER collection_immutable BEFORE UPDATE OR DELETE ON cash_collections FOR EACH ROW EXECUTE FUNCTION protect_approved();
CREATE TRIGGER approval_immutable BEFORE UPDATE OR DELETE ON hod_approvals FOR EACH ROW EXECUTE FUNCTION protect_approved();
-- RLS is defence in depth. The API always establishes context inside a transaction.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['customers','cash_collections','custody_positions','handovers','handover_allocations','receipt_confirmations','custody_ledger_entries','hod_approvals','discrepancies','adjustments','attachments','audit_events','idempotency_records'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY department_scope ON %I USING (current_setting(''app.role'',true)=''SUPER_ADMIN'' OR department_id::text=current_setting(''app.department'',true)) WITH CHECK (current_setting(''app.role'',true)=''SUPER_ADMIN'' OR department_id::text=current_setting(''app.department'',true))',t);
END LOOP; END $$;
INSERT INTO schema_migrations VALUES(1);
COMMIT;
